import { Router } from 'express';
import type { SessionBridgeService } from '../services/SessionBridgeService';
import { probeLoopbackHttp } from '../utils/portUtils';

export const createMCPRouter = (
  bridge: SessionBridgeService,
  ..._unused: unknown[]
): Router => {
  const router = Router();

  router.get('/status', async (_req, res) => {
    const devServerHealth = bridge.getDevServerHealth();
    const shouldProbeUpstream =
      bridge.isActive() &&
      devServerHealth.host !== null &&
      devServerHealth.port !== null &&
      devServerHealth.ownership !== 'none';

    if (shouldProbeUpstream && devServerHealth.port !== null) {
      const isReachable = await probeLoopbackHttp(devServerHealth.port, {
        acceptServerErrors: true,
      });
      if (isReachable) {
        bridge.updateDevServerHealth({
          isReachable: true,
          reason: 'healthy',
          lastCheckedAt: Date.now(),
        });
      } else {
        bridge.updateDevServerHealth({
          isReachable: false,
          reason: 'upstream_unreachable',
          lastCheckedAt: Date.now(),
        });
      }
    } else if (!bridge.isActive()) {
      bridge.updateDevServerHealth({
        isReachable: false,
        reason: 'rivet_unreachable',
        lastCheckedAt: Date.now(),
      });
    }

    const feedback = bridge.getFeedback();

    res.json({
      isActive: bridge.isActive(),
      hasPendingIntent: bridge.hasUnfinishedWork(),
      roundsCompleted: bridge.getRoundsCompleted(),
      apply: bridge.getChannelDepth('apply'),
      variant: bridge.getChannelDepth('variant'),
      feedback,
      status: bridge.getStatus(),
      devServerHealth: bridge.getDevServerHealth(),
    });
  });

  return router;
};
